CREATE Proc [dbo].[CreateShift] @ShiftName as nvarchar(50), @User as nvarchar(50), @Tiltid as int, @z_number as nvarchar(50) as Declare @id int; if @ShiftName <> '' begin  Select @id = count(id) from shift_opening where status = 1 if @id=0 begin if @z_number <> '' begin Insert into shift_opening( opening_date,opening_day,shift_name,z_report_number,opening_person,opening_time,status,tiltid) values(DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0),datename(dw,getdate()),@ShiftName,@z_number,@User,RIGHT(CONVERT(VARCHAR, GETDATE(), 100),7) ,1,@Tiltid) Select * from shift_opening where status = 1  end end else if @id > 0 begin Select * from shift_opening where status = 1 end end